import React from 'react';
import { render, screen } from '@testing-library/react';
import Divider from './Divider';

describe('Divider', () => {
  it('should render with orientation horizontal', () => {
    render(<Divider orientation="horizontal" data-testid="divider-component" />);
    expect(screen.getByTestId('divider-component')).toBeInTheDocument();
  });

  it('should render with orientation vertical', () => {
    render(<Divider orientation="vertical" data-testid="divider-component" />);
    expect(screen.getByTestId('divider-component')).toBeInTheDocument();
  });

  it('should render with orientation horizontal when none is passed', () => {
    render(<Divider data-testid="divider-component" />);
    expect(screen.getByTestId('divider-component')).toBeInTheDocument();
  });
});
